"""Transport-neutral Hub transfer schemas; credentials are never request fields."""
from __future__ import annotations

S = {"type": "string", "minLength": 1, "maxLength": 200}
ALIAS = {"type": "string", "pattern": r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,79}$"}
DIGEST = {"type": "string", "pattern": "^[a-f0-9]{64}$"}
P = {"project_id": S}
DEST = {"provider": ALIAS, "repo_id": {"type": "string", "minLength": 1, "maxLength": 400},
        "repo_type": {"enum": ["model", "dataset"]}, "account_alias": ALIAS}
FILES = {"type": "array", "items": {"type": "string", "minLength": 1, "maxLength": 1024},
         "minItems": 1, "maxItems": 10000, "uniqueItems": True}
BUDGET = {"type": "integer", "minimum": 1, "maximum": 2**50}


USAGE_CONTEXT = {"type": "object", "additionalProperties": False, "required": ["purpose", "commercial", "deployment", "conditions"],
    "properties": {"purpose": {"type": "string", "minLength": 1, "maxLength": 2000}, "commercial": {"type": "boolean"},
                   "deployment": S, "conditions": {"type": "array", "maxItems": 100, "items": {"type": "string", "minLength": 1, "maxLength": 2000}}}}

POLICY_FIELDS = {"reviewed_usage_context": USAGE_CONTEXT,
    "license_document_paths": FILES,
    "permitted_uses": {"type": "array", "items": {"enum": ["download", "train", "evaluate", "generate", "export", "publish", "promote"]}, "minItems": 1, "uniqueItems": True},
    "intended_context": {"type": "string", "minLength": 1, "maxLength": 4000},
    "required_files": {"type": "array", "maxItems": 100, "items": {"type": "object", "additionalProperties": False,
        "required": ["path", "sha256"], "properties": {"path": S, "sha256": DIGEST}}},
    "required_attributions": {"type": "array", "maxItems": 100, "items": {"type": "object", "additionalProperties": False,
        "required": ["path", "text"], "properties": {"path": S, "text": {"type": "string", "minLength": 1, "maxLength": 32000}}}},
    "allowed_destination_licenses": {"type": "array", "maxItems": 100, "items": S, "uniqueItems": True},
    "gated_terms_acknowledged": {"type": "boolean"}, "confirm_review": {"const": True},
}


def operation_specs(spec):
    return [
        spec("hub.license.local.inspect", "modify", "Capture exact local model, dataset or pinned source bytes and explicitly selected terms; does not infer authorship or rights.",
             {**P, "source_alias": ALIAS, "repo_type": {"enum": ["model", "dataset", "source"]}, "files": FILES, "max_bytes": BUDGET,
              "declared_license": S, "evidence_document_paths": {**FILES, "maxItems": 32},
              "source_repository_id": {"type": "string", "pattern": r"^sha256:[a-f0-9]{64}$"},
              "source_commit": {"type": "string", "pattern": r"^(?:[a-f0-9]{40}|[a-f0-9]{64})$"}}, ("project_id", "source_alias", "repo_type", "files", "max_bytes", "declared_license"), True),
        spec("hub.source.policy.bind", "modify", "Bind a current reviewed pinned-source origin to future scratch lineage; preserves all existing parents and unresolved inputs without registering model weights.",
             {**P, "recipe_id": S, "expected_revision": {"type": "integer", "minimum": 1},
              "expected_project_revision": {"type": "integer", "minimum": 1}, "license_policy_id": S,
              "intended_use": {"enum": ["train", "evaluate", "generate", "export"]}, "usage_context": USAGE_CONTEXT},
             ("project_id", "recipe_id", "expected_revision", "expected_project_revision", "license_policy_id", "intended_use", "usage_context"), True),
        spec("hub.source.policy.replace", "publish", "Explicitly replace selected direct source-origin policies for future outputs after exact old/new review; preserve immutable history, actual input parents and unresolved lineage.",
             {**P, "recipe_id": S, "expected_revision": {"type": "integer", "minimum": 1}, "expected_recipe_digest": DIGEST,
              "expected_project_revision": {"type": "integer", "minimum": 1}, "license_policy_id": S,
              "replace_source_policy_ids": {"type": "array", "items": S, "minItems": 1, "maxItems": 1000, "uniqueItems": True},
              "intended_use": {"enum": ["train", "evaluate", "generate", "export"]}, "usage_context": USAGE_CONTEXT, "confirm_replace": {"const": True}},
             ("project_id", "recipe_id", "expected_revision", "expected_recipe_digest", "expected_project_revision", "license_policy_id", "replace_source_policy_ids", "intended_use", "usage_context", "confirm_replace"), True),
        spec("hub.local.register", "modify", "Materialize exact local artifact files only after source-bound rights review; register no asset until hashes verify.",
             {**P, "evidence_id": S, "license_policy_id": S}, ("project_id", "evidence_id", "license_policy_id"), True),
        spec("hub.license.inspect", "modify", "Capture exact immutable upstream card and bounded license/notice text as evidence; never infer usage rights or accept gated terms.",
             {**P, **DEST, "remote_revision": S}, ("project_id", "provider", "repo_id", "repo_type"), True),
        spec("hub.license.get", "read", "Read captured immutable license evidence and document hashes.",
             {**P, "evidence_id": S}, ("project_id", "evidence_id")),
        spec("hub.license.review", "publish", "Record an explicit authorized review of intended uses, preserved notices, attribution and permitted destination licenses; labels alone grant nothing.",
             {**P, "evidence_id": S, "evidence_digest": DIGEST, **POLICY_FIELDS},
             ("project_id", "evidence_id", "evidence_digest", "permitted_uses", "intended_context", "required_files", "required_attributions", "allowed_destination_licenses", "gated_terms_acknowledged", "reviewed_usage_context", "license_document_paths", "confirm_review"), True),
        spec("hub.license.policy.list", "read", "List current project-scoped reviewed license policies and revocations; no credential values.", P, ("project_id",)),
        spec("hub.dataset.policy.bind", "modify", "Bind an immutable registered dataset revision to explicit reviewed per-source policies after verifying every source byte hash; never infer rights from labels.",
             {**P, "dataset_id": S, "dataset_revision": {"type": "integer", "minimum": 1},
              "source_policies": {"type": "object", "minProperties": 1, "maxProperties": 10000, "additionalProperties": S},
              "intended_use": {"enum": ["train", "evaluate", "generate", "export", "publish", "promote"]}, "usage_context": USAGE_CONTEXT},
             ("project_id", "dataset_id", "dataset_revision", "source_policies", "intended_use", "usage_context"), True),
        spec("hub.license.policy.get", "read", "Read the current project-scoped reviewed policy or revocation.",
             {**P, "policy_id": S}, ("project_id", "policy_id")),
        spec("hub.license.revoke", "publish", "Revoke a reviewed policy for future admission; preserve its immutable history and completed work.",
             {**P, "policy_id": S, "expected_revision": {"type": "integer", "minimum": 1}, "reason": S},
             ("project_id", "policy_id", "expected_revision", "reason"), True),
        spec("hub.providers", "read", "Read configured Hub capabilities, opaque account and local source aliases.", P, ("project_id",)),
        spec("hub.search", "read", "Search bounded Hub model or dataset metadata; never download weights or execute code.",
             {**P, **DEST, "query": {"type": "string", "minLength": 1, "maxLength": 200},
              "limit": {"type": "integer", "minimum": 1, "maximum": 50}}, ("project_id", "provider", "repo_type", "query")),
        spec("hub.inspect", "read", "Resolve a Hub revision to an immutable commit and inspect bounded file hashes, access and license.",
             {**P, **DEST, "remote_revision": S}, ("project_id", "provider", "repo_id", "repo_type")),
        spec("hub.repository.compare", "read", "Compare bounded local files with an immutable Hub revision; report added, modified, unchanged and remote-only paths without publishing or deleting.",
             {**P, **DEST, "source_alias": ALIAS, "remote_revision": S, "max_bytes": BUDGET},
             ("project_id", "provider", "repo_id", "repo_type", "source_alias", "max_bytes")),
        spec("hub.asset.manifest", "read", "Export a portable credential-free immutable Hub asset reference for source Git.",
             {**P, "asset_id": S}, ("project_id", "asset_id")),
        spec("hub.publish.receipt", "read", "Export a verified immutable publication receipt for source Git; no account alias or local paths.",
             {**P, "transfer_id": S}, ("project_id", "transfer_id")),
        spec("hub.download.plan", "modify", "Pin exact Hub files, license and byte budget before starting a download.",
             {**P, **DEST, "remote_revision": S, "files": FILES, "max_bytes": BUDGET, "license_policy_id": S},
             ("project_id", "provider", "repo_id", "repo_type", "files", "max_bytes", "license_policy_id"), True),
        spec("hub.download.start", "execute", "Start a pinned bounded resumable download; register no asset until all hashes verify.",
             {**P, "plan_id": S, "plan_digest": DIGEST, "accept_license": {"const": True}},
             ("project_id", "plan_id", "plan_digest", "accept_license"), True, additional_scopes=("modify",)),
        spec("hub.transfer.get", "read", "Read durable transfer progress; interrupted publication requires reconciliation, not blind retry.",
             {**P, "transfer_id": S}, ("project_id", "transfer_id")),
        spec("hub.transfer.list", "read", "List durable project Hub transfers.", P, ("project_id",)),
        spec("hub.transfer.cancel", "execute", "Request transfer cancellation; already committed uploads cannot be undone.",
             {**P, "transfer_id": S}, ("project_id", "transfer_id"), True),
        spec("hub.transfer.retry", "execute", "Resume a stopped download using its original immutable plan and verified staged files.",
             {**P, "transfer_id": S}, ("project_id", "transfer_id"), True, additional_scopes=("modify",)),
        spec("hub.asset.list", "read", "List verified project Hub assets; this does not select a base model or change the recipe.", P, ("project_id",)),
        spec("hub.asset.get", "read", "Inspect a verified Hub asset and portable resource descriptors.",
             {**P, "asset_id": S}, ("project_id", "asset_id")),
        spec("hub.asset.bind", "modify", "Add verified inert Hub file resources to the current recipe; never choose an initializer or execute remote code.",
             {**P, "asset_id": S, "expected_revision": {"type": "integer", "minimum": 1}, "usage_context": USAGE_CONTEXT},
             ("project_id", "asset_id", "expected_revision"), True),
        spec("hub.local.files", "read", "List bounded relative files in an operator-approved project publication source alias.",
             {**P, "source_alias": ALIAS}, ("project_id", "source_alias")),
        spec("hub.publish.preview", "modify", "Snapshot exact model or dataset files and preview destination, visibility, license and change effects; never upload.",
             {**P, **DEST, "source_alias": ALIAS, "asset_id": S, "source_asset_ids": {"type": "array", "items": S, "minItems": 1, "maxItems": 1000, "uniqueItems": True}, "files": FILES, "max_bytes": BUDGET,
              "visibility": {"enum": ["private", "public"]}, "license": {"type": "string", "pattern": r"^[a-z0-9][a-z0-9.-]{0,79}$"},
              "usage_context": USAGE_CONTEXT, "create_repo": {"type": "boolean"}, "expected_remote_commit": {"type": "string", "minLength": 1, "maxLength": 512}},
             ("project_id", "provider", "repo_id", "repo_type", "account_alias", "files", "max_bytes", "visibility", "license", "usage_context"), True),
        spec("hub.publish.discard", "modify", "Discard this actor's unused derived publication snapshot; source files and audit receipts remain.",
             {**P, "preview_id": S}, ("project_id", "preview_id"), True),
        spec("hub.publish.approve", "publish", "Approve this exact publication payload digest; approval is actor/project-bound and one-use.",
             {**P, "preview_id": S, "payload_digest": DIGEST, "confirm_publication": {"const": True}},
             ("project_id", "preview_id", "payload_digest", "confirm_publication"), True),
        spec("hub.publish.start", "publish", "Consume exact approval and publish only its frozen files; verify the resulting immutable commit.",
             {**P, "preview_id": S, "payload_digest": DIGEST, "approval_id": S},
             ("project_id", "preview_id", "payload_digest", "approval_id"), True, additional_scopes=("execute",)),
        spec("hub.publish.reconcile", "publish", "Read remote commit history to reconcile an uncertain publication without submitting it again.",
             {**P, "transfer_id": S}, ("project_id", "transfer_id"), True),
    ]
